examples.template:
Column(
    horizontalAlignment = Alignment.End,
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
) {
    Box {
        MonarchButton(
            text = {{menu.trigger}},
            onClick = { expanded = true },
            modifier = Modifier.semantics { stateDescription = "${visible.size} of ${columns.size} shown" },
            size = MonarchButtonSize.Sm,
            leadingIcon = { MonarchIcon(SampleIcons.Columns, contentDescription = null) },
        )
        MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
            MonarchMenuLabel(text = "Visible columns")
            columns.forEach { column ->
                val shown = column.id in visible
                MonarchMenuItem(
                    text = column.title,
                    onClick = { visible = if (shown) visible - column.id else visible + column.id },
                    enabled = column.hideable && !(shown && visible.size == 1),
                    selected = shown,
                )
            }
            MonarchMenuDivider()
            MonarchMenuItem(
                text = {{menu.showAll}},
                onClick = {
                    visible = columns.map { it.id }.toSet()
                    expanded = false
                },
                enabled = visible.size < columns.size,
            )
            MonarchMenuItem(
                text = "Reset columns",
                onClick = {
                    visible = columns.filterNot { it.hidden }.map { it.id }.toSet()
                    expanded = false
                },
            )
        }
    }
    // Room for the open menu above the table, as on the web.
    Spacer(Modifier.height(MonarchTheme.spacing.space24 * 3 + MonarchTheme.spacing.space8))
    MonarchDataTable(
        caption = {{caption}},
        rows = domains,
        columns = columns.map { column ->
            MonarchDataTableColumn<Domain>(column.title, id = column.id, hideable = column.hideable) { it.value(column.id) }
        },
        rowKey = { it.id },
        layout = MonarchDataTableLayout.Table,
        hiddenColumns = columns.map { it.id }.toSet() - visible,
    )
}

